{"refs":["alphabet","length","modulus","residue","sum_min","sum_max","target_digit","target_count"],"code":"def solve(facts):
    alphabet = facts['alphabet']
    length = facts['length']
    modulus = facts['modulus']
    residue = facts['residue']
    sum_min = facts['sum_min']
    sum_max = facts['sum_max']
    target_digit = facts['target_digit']
    target_count = facts['target_count']
    # State: last digit, residue, sum, target count -> (ways, total digit sums)
    dp = {}
    for d in alphabet:
        key = (d, d % modulus, d, int(d == target_digit))
        dp[key] = (1, d)
    for _ in range(1, length):
        ndp = {}
        for (last, rem, total, count), (ways, digit_sums) in dp.items():
            for d in alphabet:
                if d == last:
                    continue
                ns = total + d
                nc = count + int(d == target_digit)
                if ns > sum_max or nc > target_count:
                    continue
                key = (d, (rem * 10 + d) % modulus, ns, nc)
                old_ways, old_sums = ndp.get(key, (0, 0))
                ndp[key] = (old_ways + ways, old_sums + digit_sums + ways * d)
        dp = ndp
    count_total = 0
    digit_sum_total = 0
    for (last, rem, total, count), (ways, digit_sums) in dp.items():
        if rem == residue and sum_min <= total <= sum_max and count == target_count:
            count_total += ways
            digit_sum_total += digit_sums
    return {'count': count_total, 'digit_sum_total': digit_sum_total}

def check(answer, facts):
    alphabet = facts['alphabet']
    length = facts['length']
    modulus = facts['modulus']
    residue = facts['residue']
    sum_min = facts['sum_min']
    sum_max = facts['sum_max']
    target_digit = facts['target_digit']
    target_count = facts['target_count']
    # Independent meet-in-the-middle enumeration of halves and boundary joins.
    split = length // 2
    left_len = split
    right_len = length - split
    def halves(n):
        if n == 0:
            return [('', 0, 0, 0, -1)]
        rows = [('', 0, 0, 0, -1)]
        for _ in range(n):
            nxt = []
            for s, rem, sm, ct, last in rows:
                for d in alphabet:
                    if d == last:
                        continue
                    nxt.append((s + chr(48 + d), (rem * 10 + d) % modulus, sm + d, ct + int(d == target_digit), d))
            rows = nxt
        return rows
    left = halves(left_len)
    right = halves(right_len)
    count_total = 0
    sum_total = 0
    pow10 = pow(10, right_len, modulus)
    for ls, lr, lsm, lct, ll in left:
        for rs, rr, rsm, rct, rl in right:
            if ll == rl or lct + rct != target_count:
                continue
            total = lsm + rsm
            if not (sum_min <= total <= sum_max):
                continue
            if (lr * pow10 + rr) % modulus == residue:
                count_total += 1
                sum_total += total
    return isinstance(answer, dict) and answer.get('count') == count_total and answer.get('digit_sum_total') == sum_total"}

